/**
 * Cached results of finished rounds (public/data/results.json, generated by
 * scripts/build-gameweeks.mjs and refreshed weekly). Loading old results from
 * one static, same-origin file is far faster than hitting ESPN once per past
 * round on every load. Live/in-progress rounds are still fetched from ESPN.
 */
import type { Fixture } from './espn'

let cache: Map<number, Fixture[]> | null = null

export async function loadResults(): Promise<Map<number, Fixture[]>> {
  if (cache) return cache
  try {
    const res = await fetch(`${import.meta.env.BASE_URL}data/results.json`)
    if (!res.ok) return new Map()
    const data = await res.json()
    const m = new Map<number, Fixture[]>()
    for (const [round, fixtures] of Object.entries(data.rounds ?? {})) {
      m.set(Number(round), fixtures as Fixture[])
    }
    cache = m
    return m
  } catch {
    return new Map()
  }
}
